<?php $title='Sonderberichte'; $statusLabel=['draft'=>'Entwurf','in_progress'=>'In Bearbeitung','revision_required'=>'Nachbearbeitung','completed'=>'Ungeprüft','reviewed'=>'Geprüft']; ?>
<div class="page-header split"><div><p class="eyebrow">Sonderberichte</p><h1>Arbeitsübersicht</h1><p>Entwürfe, Nachbearbeitungen und Leitungsprüfung auf einen Blick.</p></div><?php if(can('special_reports.create')):?><a class="button primary" href="<?= e(url('special-reports/create')) ?>">+ Sonderbericht</a><?php endif;?></div>
<div class="toolbar"><a class="button ghost" href="<?= e(url('special-reports/search')) ?>">Suche & Archiv</a></div>
<?php foreach([['Nachbearbeitung erforderlich',$revision],['Ungeprüft – Leitungsprüfung',$unreviewed],['In Bearbeitung',$open],['Entwürfe',$drafts],['Kürzlich geprüft',$reviewed]] as [$heading,$group]):?>
<div class="panel"><div class="panel-header"><div><h2><?= e($heading) ?></h2><p><?= (int)$group['total'] ?> Bericht(e)</p></div></div><div class="table-wrap"><table><thead><tr><th>Nummer</th><th>Datum</th><th>Einsatzart</th><th>Ersteller</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($group['items'] as $r):?><tr><td><strong><?= e(str_pad((string)$r['report_number'],4,'0',STR_PAD_LEFT).'/'.$r['report_year']) ?></strong></td><td><?= e((new DateTimeImmutable($r['incident_date']))->format('d.m.Y')) ?></td><td><?= e($r['report_type_name']) ?></td><td><?= e($r['creator_name']??'–') ?></td><td><span class="badge status-<?= e($r['status']) ?>"><?= e($statusLabel[$r['status']]??$r['status']) ?></span></td><td class="align-right"><a class="button ghost compact" href="<?= e(url('special-reports/'.$r['id'])) ?>">Öffnen</a></td></tr><?php endforeach;?><?php if($group['items']===[]):?><tr><td colspan="6" class="empty">Keine Einträge.</td></tr><?php endif;?></tbody></table></div></div>
<?php endforeach;?>
